export const canonical39RetiredTargetDatabaseBytes = (scenario: Canonical39RetiredTargetScenario): Buffer => {
  const fixture = canonical39RetiredTargetFixtures[scenario];
  const recipe = readFileSync(new URL("./canonical39-retired-targets-generator.original.ts.txt", import.meta.url));
  if (createHash("sha256").update(recipe).digest("hex") !== fixture.generatorSha256) {
    throw new Error("Canonical39 retired target recipe changed.");
  }
  const bytes = gunzipSync(Buffer.from(images[scenario], "base64"), { maxOutputLength: fixture.databaseBytes });
  if (bytes.length !== fixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== fixture.databaseSha256) {
    throw new Error("Canonical39 retired target image changed.");
  }
  return bytes;
};
